UPDATE daily_plan
        SET weekly_plan_id=#{weeklyPlanId},
            plan_date=#{planDate},
            version=version+1,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=#{id}
          AND user_id=#{userId}
          AND version=#{version}
          AND deleted_at IS NULL

UPDATE daily_plan
        SET deleted_at=CURRENT_TIMESTAMP,version=version+1,updated_at=CURRENT_TIMESTAMP
        WHERE id=#{id}
          AND user_id=#{userId}
          AND version=#{version}
          AND deleted_at IS NULL
